 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    divider = next(c for c in range(w) if all(grid[r][c] == grid[0][c] != 0 for r in range(h)))
    width = w - divider - 1
    out = [[0] * width for _ in range(h)]
    y, x = next((r, c-divider-1) for r in range(h) for c in range(divider+1,w) if grid[r][c] == 5)
    out[y][x] = 5

    # The repeated 3x3 motifs are movement glyphs. Extract connected motif
    # cells per four-row band; classify each glyph by its color and shape.
    for top in range(0, h-2, 4):
        for c0 in (0, 4):
            patch = [row[c0:c0+3] for row in grid[top:top+3]]
            vals = [v for row in patch for v in row if v]
            if not vals:
                continue
            color = vals[0]
            y += 1
            if color == 6:
                # A 6 motif is the vertical/down glyph.
                for _ in range(2):
                    if 0 <= y < h and 0 <= x < width:
                        out[y][x] = color
                    y += 1
                y -= 1
                continue
            # 1 is rightward, 2 and 3 are leftward. Length is encoded by glyph
            # density (not simply color); inspect its occupied cell count.
            count = len(vals)
            if color == 1:
                dx, length = 1, 3
            elif color == 2:
                dx, length = -1, 2 if count <= 7 else 3
            elif color == 3:
                dx, length = -1, 4
            else:
                continue
            for _ in range(length):
                if 0 <= y < h and 0 <= x < width:
                    out[y][x] = color
                x += dx
            x -= dx
    return out

if __name__ == '__main__':
    pass
