 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    divider = next(c for c in range(w) if all(grid[r][c] == grid[0][c] != 0 for r in range(h)))
    width = w - divider - 1
    out = [[0] * width for _ in range(h)]

    # The input motifs are symbols in a two-lane, four-row-spaced code. The
    # marker gives the starting cell. Each motif contributes a short colored
    # stroke in a fixed lane of the output diagram.
    marker = next((r, c - divider - 1) for r in range(h)
                  for c in range(divider + 1, w) if grid[r][c] == 5)
    out[marker[0]][marker[1]] = 5
    for top in range(0, h - 2, 4):
        for lane, c0 in enumerate((0, 4)):
            patch = [grid[r][c0:c0 + 3] for r in range(top, top + 3)]
            vals = [v for row in patch for v in row if v]
            if not vals:
                continue
            color = vals[0]
            y = min(h - 1, top + lane + 1)
            x = marker[1]
            if color == 6:
                for yy in range(y, min(h, y + 2)):
                    out[yy][x] = color
            elif color in (1, 2, 3):
                length = {1: 3, 2: 2, 3: 4}[color]
                start = max(0, min(width - length, x - length // 2))
                for xx in range(start, start + length):
                    out[y][xx] = color
    return out

