    h, w = len(grid), len(grid[0])
    # The divider separates the key panel from a blank answer canvas. Preserve
    # its width, and place the start marker in its relative position.
    divider = next(c for c in range(w) if all(grid[r][c] == grid[0][c] != 0 for r in range(h)))
    width = w - divider - 1
    out = [[0] * width for _ in range(h)]
    mr, mc = next((r, c-divider-1) for r in range(h)
                  for c in range(divider+1, w) if grid[r][c] == 5)
    out[mr][mc] = 5

    # The two columns of 3x3 glyphs form a sequence of instructions. Glyph
    # silhouette selects the stroke type; apply each instruction from the
    # marker, advancing to a new row after the stroke.
    glyphs = {
        '110101010': (1, 1, 3),  # color, horizontal direction, stroke length
        '202202222': (2, -1, 2),
        '606060060': (6, 0, 2),
        '333030303': (3, -1, 4),
    }
    y, x = mr, mc
    for top in range(0, h-2, 4):
        for c0 in (0, divider-4):
            p = [row[c0:c0+3] for row in grid[top:top+3]]
            vals = [v for row in p for v in row if v]
            if not vals:
                continue
            signature = ''.join(str(v) for row in p for v in row)
            color, direction, length = glyphs.get(signature, (vals[0], 0, 1))
            if direction == 0:
                for _ in range(length):
                    y += 1
                    if 0 <= y < h and 0 <= x < width:
                        out[y][x] = color
            else:
                y += 1
                for _ in range(length):
                    if 0 <= y < h and 0 <= x < width:
                        out[y][x] = color
                    x += direction
                x -= direction
    return out

if __name__ == '__main__':
